CREATE TABLE "rux_cases" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_cases_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"guild_id" varchar(32) NOT NULL,
	"action" varchar(24) NOT NULL,
	"target_id" varchar(32),
	"target_name" varchar(400),
	"channel_id" varchar(32),
	"moderator_discord_id" varchar(32) NOT NULL,
	"moderator_account_id" bigint,
	"moderator_user_uuid" uuid,
	"reason" varchar(2000),
	"duration_seconds" integer,
	"automatic" boolean DEFAULT false NOT NULL,
	"rule_id" bigint,
	"expires" timestamp,
	"resolved" timestamp,
	"revoked" timestamp,
	"meta" jsonb,
	"created" timestamp DEFAULT now() NOT NULL,
	"updated" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_giveaway_entries" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_giveaway_entries_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"giveaway_id" bigint NOT NULL,
	"discord_id" varchar(32) NOT NULL,
	"username" varchar(256),
	"won" timestamp,
	"draw" smallint,
	"payout" varchar(16),
	"created" timestamp DEFAULT now() NOT NULL,
	"updated" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_giveaways" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_giveaways_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"guild_id" varchar(32) NOT NULL,
	"channel_id" varchar(32) NOT NULL,
	"message_id" varchar(32),
	"prize" varchar(480) NOT NULL,
	"credits" bigint NOT NULL,
	"winners_count" smallint DEFAULT 1 NOT NULL,
	"ends" timestamp NOT NULL,
	"exclude_recent" smallint DEFAULT 0 NOT NULL,
	"excluded" jsonb,
	"status" varchar(16) DEFAULT 'active' NOT NULL,
	"created_by_discord_id" varchar(32) NOT NULL,
	"created_by_account_id" bigint,
	"created_by_user_uuid" uuid,
	"ended" timestamp,
	"payout_status" varchar(16) DEFAULT 'none' NOT NULL,
	"payout_attempts" integer DEFAULT 0 NOT NULL,
	"payout_error" varchar(255),
	"payout_reference" varchar(64),
	"rerolls" smallint DEFAULT 0 NOT NULL,
	"rendered_entries" integer DEFAULT 0 NOT NULL,
	"created" timestamp DEFAULT now() NOT NULL,
	"updated" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_messages" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_messages_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"conversation" varchar(80) NOT NULL,
	"turn_id" bigint,
	"discord_message_id" varchar(32),
	"channel_id" varchar(32) NOT NULL,
	"guild_id" varchar(32),
	"author_id" varchar(32) NOT NULL,
	"author_name" varchar(400),
	"role" varchar(16) NOT NULL,
	"content" text,
	"tool_calls" jsonb,
	"tool_call_id" varchar(64),
	"tool_name" varchar(64),
	"status" varchar(16) DEFAULT 'done' NOT NULL,
	"meta" jsonb,
	"created" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_moderator_roles" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_moderator_roles_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"guild_id" varchar(32) NOT NULL,
	"role_id" varchar(32) NOT NULL,
	"role_name" varchar(400),
	"granted_by_discord_id" varchar(32) NOT NULL,
	"granted_by_account_id" bigint,
	"granted_by_user_uuid" uuid,
	"permissions_added" varchar(32) DEFAULT '0' NOT NULL,
	"created" timestamp DEFAULT now() NOT NULL,
	"updated" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_rules" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_rules_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"guild_id" varchar(32) NOT NULL,
	"description" varchar(2400) NOT NULL,
	"exceptions" varchar(2400),
	"keywords" jsonb DEFAULT '[]' NOT NULL,
	"action" varchar(16) NOT NULL,
	"duration_seconds" integer,
	"delete_message" boolean DEFAULT false NOT NULL,
	"reason" varchar(1200),
	"channel_ids" jsonb,
	"active" boolean DEFAULT true NOT NULL,
	"created_by_discord_id" varchar(32) NOT NULL,
	"created_by_account_id" bigint,
	"created_by_user_uuid" uuid,
	"hits" integer DEFAULT 0 NOT NULL,
	"actions" integer DEFAULT 0 NOT NULL,
	"last_action" timestamp,
	"created" timestamp DEFAULT now() NOT NULL,
	"updated" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_watch_items" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_watch_items_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"guild_id" varchar(32),
	"message_id" varchar(32) NOT NULL,
	"channel_id" varchar(32) NOT NULL,
	"author_id" varchar(32) NOT NULL,
	"author_name" varchar(400),
	"roles" jsonb,
	"content" text NOT NULL,
	"replied_to" text,
	"created" timestamp DEFAULT now() NOT NULL
);

CREATE TABLE "rux_watches" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rux_watches_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"guild_id" varchar(32) NOT NULL,
	"channel" varchar(400) NOT NULL,
	"added_by_discord_id" varchar(32),
	"created" timestamp DEFAULT now() NOT NULL,
	"updated" timestamp DEFAULT now() NOT NULL
);

CREATE INDEX "rux_cases_guild_id_target_id_idx" ON "rux_cases" ("guild_id","target_id");
CREATE INDEX "rux_cases_action_expires_resolved_idx" ON "rux_cases" ("action","expires","resolved");
CREATE INDEX "rux_cases_created_idx" ON "rux_cases" ("created");
CREATE UNIQUE INDEX "rux_giveaway_entries_giveaway_id_discord_id_idx" ON "rux_giveaway_entries" ("giveaway_id","discord_id");
CREATE INDEX "rux_giveaway_entries_discord_id_idx" ON "rux_giveaway_entries" ("discord_id");
CREATE INDEX "rux_giveaways_ends_idx" ON "rux_giveaways" ("ends");
CREATE INDEX "rux_giveaways_status_idx" ON "rux_giveaways" ("status");
CREATE INDEX "rux_giveaways_payout_status_idx" ON "rux_giveaways" ("payout_status");
CREATE INDEX "rux_messages_conversation_idx" ON "rux_messages" ("conversation");
CREATE INDEX "rux_messages_turn_id_idx" ON "rux_messages" ("turn_id");
CREATE INDEX "rux_messages_role_status_idx" ON "rux_messages" ("role","status");
CREATE INDEX "rux_messages_created_idx" ON "rux_messages" ("created");
CREATE UNIQUE INDEX "rux_moderator_roles_guild_id_role_id_idx" ON "rux_moderator_roles" ("guild_id","role_id");
CREATE INDEX "rux_rules_guild_id_active_idx" ON "rux_rules" ("guild_id","active");
CREATE INDEX "rux_watch_items_created_idx" ON "rux_watch_items" ("created");
CREATE UNIQUE INDEX "rux_watches_guild_id_channel_idx" ON "rux_watches" ("guild_id","channel");
ALTER TABLE "rux_cases" ADD CONSTRAINT "rux_cases_moderator_user_uuid_users_uuid_fkey" FOREIGN KEY ("moderator_user_uuid") REFERENCES "users"("uuid") ON DELETE SET NULL;
ALTER TABLE "rux_cases" ADD CONSTRAINT "rux_cases_rule_id_rux_rules_id_fkey" FOREIGN KEY ("rule_id") REFERENCES "rux_rules"("id") ON DELETE SET NULL;
ALTER TABLE "rux_giveaway_entries" ADD CONSTRAINT "rux_giveaway_entries_giveaway_id_rux_giveaways_id_fkey" FOREIGN KEY ("giveaway_id") REFERENCES "rux_giveaways"("id") ON DELETE CASCADE;
ALTER TABLE "rux_giveaways" ADD CONSTRAINT "rux_giveaways_created_by_user_uuid_users_uuid_fkey" FOREIGN KEY ("created_by_user_uuid") REFERENCES "users"("uuid") ON DELETE SET NULL;
ALTER TABLE "rux_moderator_roles" ADD CONSTRAINT "rux_moderator_roles_granted_by_user_uuid_users_uuid_fkey" FOREIGN KEY ("granted_by_user_uuid") REFERENCES "users"("uuid") ON DELETE SET NULL;
ALTER TABLE "rux_rules" ADD CONSTRAINT "rux_rules_created_by_user_uuid_users_uuid_fkey" FOREIGN KEY ("created_by_user_uuid") REFERENCES "users"("uuid") ON DELETE SET NULL;